41	const PROCESSING_FEE = 5;
42	
43	const CURSE_SURCHARGE = 0.5;
44	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
45	const LOYALTY_DISCOUNT = -0.2;
46	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
47	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
48	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
49	
50	/** The MHPCO price list; only the types pinned down by tests so far. */
51	const BASE_PREMIUMS: Record<string, number | undefined> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	  moonstone: 25,
58	};
59	
60	/** What each item is insured for; distinct from what it costs to insure. */
61	const INSURANCE_VALUES: Record<string, number | undefined> = {
62	  sword: 1000,
63	  amulet: 600,
64	  staff: 800,
65	  potion: 400,
66	  rune: 250,
67	  moonstone: 250,
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
72	
73	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
74	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
75	
76	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
77	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
78	
79	/** Payouts are rounded in the MHPCO's favour too — which for money paid out is down. */
80	const roundDownToWholeG = (amount: number): number => Math.floor(withoutFloatNoise(amount));
81	
82	/** Every price list is keyed by item type, and an unlisted type is never priceable. */
83	const listedAmountFor = (priceList: Record<string, number | undefined>) =>
84	  (item: Item): number => {
85	    const amount = priceList[item.type];
86	    if (amount === undefined) throw new Error(`Unknown item type: ${item.type}`);
87	    return amount;
88	  };
89	
90	const basePremiumFor = listedAmountFor(BASE_PREMIUMS);
91	const insuranceValueFor = listedAmountFor(INSURANCE_VALUES);
92	
93	/** Sums a projection over a list: the amounts, rates, or values it maps to. */
94	const sumOf = <T>(values: T[], numberFor: (value: T) => number): number =>
95	  values.reduce((total, value) => total + numberFor(value), 0);
96	
97	/** A building block of 3 alike components is offered at a special base premium. */
98	const BLOCK_SIZE = 3;
99	const BLOCK_BASE_PREMIUM = 60;
100	
101	/** Components are the small parts; main items never qualify for block pricing. */
102	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
103	
104	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
105	
106	/** Block pricing is decided per type, so items are priced in same-type groups. */
107	const groupedByType = (items: Item[]): Item[][] => {
108	  const groups = new Map<string, Item[]>();
109	  for (const item of items) {
110	    const group = groups.get(item.type);
111	    if (group === undefined) groups.set(item.type, [item]);
112	    else group.push(item);
113	  }
114	  return [...groups.values()];
115	};
116	
117	/**
118	 * A group is same-type by construction, so one member settles whether the group
119	 * is made of components.
120	 */
121	const isBlock = (group: Item[]): boolean =>
122	  group.length === BLOCK_SIZE && isComponent(group[0]);
123	
124	const basePremiumForGroup = (group: Item[]): number =>
125	  isBlock(group) ? BLOCK_BASE_PREMIUM : sumOf(group, basePremiumFor);
126	
127	const HIGH_ENCHANTMENT_THRESHOLD = 5;
128	
129	const isCursed = (item: Item): boolean => item.cursed === true;
130	
131	const isHighlyEnchanted = (item: Item): boolean =>
132	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
133	
134	/**
135	 * A modifier raises or lowers the amount it applies to by `rate`, but only for
136	 * subjects it applies to. Modifiers that apply stack additively.
137	 */
138	interface Modifier<Subject> {
139	  appliesTo: (subject: Subject) => boolean;
140	  rate: number;
141	}
142	
143	const combinedRateOf = <Subject>(
144	  modifiers: Modifier<Subject>[],
145	  subject: Subject,
146	): number => sumOf(modifiers, ({ appliesTo, rate }) => (appliesTo(subject) ? rate : 0));
147	
148	/** Item-specific modifiers are levied on the affected item's own base premium. */
149	const ITEM_MODIFIERS: Modifier<Item>[] = [
150	  { appliesTo: isCursed, rate: CURSE_SURCHARGE },
151	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
152	];
153	
154	const itemSurchargeFor = (item: Item): number =>
155	  basePremiumFor(item) * combinedRateOf(ITEM_MODIFIERS, item);
156	
157	const LOYALTY_THRESHOLD_YEARS = 2;
158	
159	/**
160	 * The circumstances a single quote is issued under: who is being quoted, and
161	 * where this contract falls in their history with the MHPCO. Policy-wide
162	 * modifiers are decided from this alone.
163	 */
164	interface QuoteContext {
165	  customer: Customer;
166	  isFollowUpContract: boolean;
167	}
168	
169	const isLongStanding = ({ customer }: QuoteContext): boolean =>
170	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
171	
172	const followsAnEarlierContract = ({ isFollowUpContract }: QuoteContext): boolean =>
173	  isFollowUpContract;
174	
175	const appliesToEveryQuote = (): boolean => true;
176	
177	/** Policy-wide modifiers are levied on the whole policy's base premium. */
178	const POLICY_MODIFIERS: Modifier<QuoteContext>[] = [
179	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT },
180	  { appliesTo: appliesToEveryQuote, rate: INITIAL_ASSESSMENT_SURCHARGE },
181	  { appliesTo: followsAnEarlierContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT },
182	];
183	
184	/**
185	 * Item-specific modifiers are levied on the affected item's own base premium,
186	 * while policy-wide modifiers are levied on the policy base premium — the sum
187	 * of the item base premiums, before any item surcharge is added.
188	 */
189	const quote = (step: QuoteStep, context: QuoteContext): StepResult => {
190	  const policyBasePremium = sumOf(groupedByType(step.items), basePremiumForGroup);
191	  const itemSurcharges = sumOf(step.items, itemSurchargeFor);
192	  const policyAdjustment = policyBasePremium * combinedRateOf(POLICY_MODIFIERS, context);
193	  return {
194	    premium: roundUpToWholeG(
195	      policyBasePremium + itemSurcharges + policyAdjustment + PROCESSING_FEE,
196	    ),
197	  };
198	};
199	
200	/** A policy created by a quote step, against which later claims are settled. */
201	interface Policy {
202	  items: Item[];
203	  remainingCap: number;
204	}
205	
206	const policyFor = (step: QuoteStep): Policy => ({
207	  items: step.items,
208	  remainingCap: sumOf(step.items, insuranceValueFor) * CAP_MULTIPLE_OF_INSURANCE_SUM,
209	});
210	
211	/**
212	 * Damage to a very strongly enchanted item is only half reimbursed. This
213	 * threshold is deliberately distinct from the premium side's
214	 * HIGH_ENCHANTMENT_THRESHOLD: the same attribute is read by two unrelated rules.
215	 */
216	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
217	const HALF_REIMBURSEMENT_RATE = 0.5;
218	const FULL_REIMBURSEMENT_RATE = 1;
219	
220	const isTooEnchantedToFullyReimburse = (item: Item): boolean =>
221	  item.enchantment !== undefined &&
222	  item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
223	
224	const reimbursementRateFor = (item: Item): number =>
225	  isTooEnchantedToFullyReimburse(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
226	
227	/** One damage settled against the one insured item it is charged against. */
228	interface Charge {
229	  damage: Damage;
230	  item: Item;
231	}
232	
233	/**
234	 * A negative amount is malformed input rather than a small claim, so it is
235	 * rejected outright. A legitimately small positive damage is not an error: it
236	 * falls below the deductible and simply pays nothing.
237	 */
238	const rejectMalformed = (damage: Damage): Damage => {
239	  if (damage.amount < 0) {
240	    throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
241	  }
242	  return damage;
243	};
244	
245	/**
246	 * Every damage is charged against a distinct insured item, so a policy covering
247	 * one sword cannot answer for two damaged swords: each match consumes the item
248	 * it charges. Claiming for more items of a type than the policy covers rejects
249	 * the whole claim.
250	 */
251	const chargesFor = (damages: Damage[], insuredItems: Item[]): Charge[] => {
252	  const unclaimed = [...insuredItems];
253	  return damages.map((damage) => {
254	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
255	    if (index === -1) throw new Error(`Item not insured: ${damage.itemType}`);
256	    return { damage, item: unclaimed.splice(index, 1)[0] };
257	  });
258	};
259	
260	/**
261	 * The clause is applied to the damage first; the deductible comes off the result.
262	 * The deductible can reduce a charge to nothing but never below it, so a damage
263	 * smaller than the deductible pays nothing rather than clawing back from the
264	 * other damages in the same incident.
265	 */
266	const deductedReimbursementFor = ({ damage, item }: Charge): number => {
267	  const reimbursed = damage.amount * reimbursementRateFor(item);
268	  return Math.max(reimbursed - DEDUCTIBLE_PER_DAMAGE, 0);
269	};
270	
271	/** Claims name the quote step that created the policy they are settled against. */
272	const policyAt = (policies: Map<number, Policy>, step: number): Policy => {
273	  const policy = policies.get(step);
274	  if (policy === undefined) throw new Error(`No policy at step ${step}`);
275	  return policy;
276	};
277	
278	/**
279	 * A claim both reports a payout and draws down the policy's cap, so settling one
280	 * yields the settled policy rather than mutating it: successive claims against
281	 * the same policy are then an explicit chain, not a hidden shared-state effect.
282	 */
283	const claim = (
284	  step: ClaimStep,
285	  policy: Policy,
286	): { result: StepResult; policy: Policy } => {
287	  const damages = step.incident.damages.map(rejectMalformed);
288	  const charges = chargesFor(damages, policy.items);
289	  const reimbursementBeforeCap = sumOf(charges, deductedReimbursementFor);
290	  const payout = roundDownToWholeG(Math.min(reimbursementBeforeCap, policy.remainingCap));
291	  const remainingCap = policy.remainingCap - payout;
292	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
293	};
294	
295	/**
296	 * Steps are not independent: a quote's premium depends on whether an earlier
297	 * quote in the same scenario already established a contract, and a claim is
298	 * settled against the policy an earlier quote created.
299	 */
300	export const runScenario = (scenario: Scenario): ScenarioResult => {
301	  const policies = new Map<number, Policy>();
302	  let hasQuoted = false;
303	
304	  const results = scenario.steps.map((step, index) => {
305	    if (step.op === "quote") {
306	      const result = quote(step, {
307	        customer: scenario.customer,
308	        isFollowUpContract: hasQuoted,
309	      });
310	      policies.set(index, policyFor(step));
311	      hasQuoted = true;
312	      return result;
313	    }
314	
315	    const { result, policy: settledPolicy } = claim(step, policyAt(policies, step.policy));
316	    policies.set(step.policy, settledPolicy);
317	    return result;
318	  });
319	
320	  return { results };
321	};
